/* Generated by scripts/generate.mjs — progressive enhancement for Awesome NSH */
(function () {
  var isZh = (document.documentElement.lang || '').toLowerCase().indexOf('zh') === 0;
  var liveEl = document.getElementById('live-status');

  function announce(msg) {
    if (liveEl) {
      liveEl.textContent = '';
      setTimeout(function () {
        liveEl.textContent = msg;
      }, 20);
    }
  }

  function updateThemeBtn() {
    var btn = document.getElementById('theme-toggle');
    if (!btn) return;
    var isDark = document.documentElement.classList.contains('dark');
    var labelEl = btn.querySelector('[data-theme-label]');
    if (labelEl) {
      labelEl.textContent = isZh
        ? (isDark ? '浅色模式' : '深色模式')
        : (isDark ? 'Light mode' : 'Dark mode');
    }
    btn.setAttribute('aria-pressed', isDark ? 'true' : 'false');
  }

  var themeBtn = document.getElementById('theme-toggle');
  if (themeBtn) {
    updateThemeBtn();
    themeBtn.addEventListener('click', function () {
      var root = document.documentElement;
      var next = root.classList.contains('dark') ? 'light' : 'dark';
      root.dataset.themePref = next;
      try { localStorage.setItem('nsh_awesome_theme', next); } catch (e) {}
      if (typeof window.__applyAwesomeTheme === 'function') {
        window.__applyAwesomeTheme();
      }
      updateThemeBtn();
    });
  }

  function fallbackCopy(text, cb) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
    cb();
  }

  function handleCopy(btn) {
    var text = btn.getAttribute('data-copy');
    if (!text) return;
    var labelEl = btn.querySelector('[data-copy-label]') || btn;
    var original = labelEl.textContent;
    function done() {
      labelEl.textContent = isZh ? '已复制' : 'Copied';
      btn.classList.add('is-copied');
      announce((isZh ? '已复制：' : 'Copied: ') + text);
      setTimeout(function () {
        labelEl.textContent = original;
        btn.classList.remove('is-copied');
      }, 1400);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(function () {
        fallbackCopy(text, done);
      });
    } else {
      fallbackCopy(text, done);
    }
  }

  document.addEventListener('click', function (ev) {
    var copyBtn = ev.target.closest('[data-copy]');
    if (copyBtn) {
      handleCopy(copyBtn);
    }
  });

  // Home catalog progressive filtering over SSR-rendered cards
  var catalogRoot = document.getElementById('catalog-root');
  var searchInput = document.getElementById('search-input');
  var sourceSelect = document.getElementById('source-filter');
  var secWrap = document.getElementById('section-chips');
  var catWrap = document.getElementById('category-chips');
  var summaryEl = document.getElementById('results-summary');
  var clearBtn = document.getElementById('clear-filters');
  var emptyEl = document.getElementById('empty-state');
  var searchForm = document.getElementById('catalog-search-form');

  if (catalogRoot && searchInput && sourceSelect) {
    var cards = Array.prototype.slice.call(catalogRoot.querySelectorAll('article.card'));
    var sections = Array.prototype.slice.call(catalogRoot.querySelectorAll('section.section-block'));
    var params = new URLSearchParams(location.search);
    var state = {
      section: 'all',
      category: 'all',
      source: params.get('source') || 'all',
      query: (params.get('q') || '').trim().toLowerCase()
    };

    if (state.query) searchInput.value = params.get('q').trim();
    if (sourceSelect.querySelector('option[value="' + state.source.replace(/"/g, '') + '"]')) {
      sourceSelect.value = state.source;
    } else {
      state.source = 'all';
    }

    function syncUrl() {
      if (typeof history === 'undefined' || !history.replaceState) return;
      var nextParams = new URLSearchParams(location.search);
      if (state.query) nextParams.set('q', state.query);
      else nextParams.delete('q');
      if (state.source && state.source !== 'all') nextParams.set('source', state.source);
      else nextParams.delete('source');
      var qs = nextParams.toString();
      var nextUrl = location.pathname + (qs ? '?' + qs : '') + location.hash;
      history.replaceState(null, '', nextUrl);
    }

    function applyFilters(shouldSyncUrl) {
      var visibleTotal = 0;

      cards.forEach(function (card) {
        var sec = card.getAttribute('data-section') || '';
        var cat = card.getAttribute('data-category') || '';
        var src = card.getAttribute('data-source') || '';
        var hay = card.getAttribute('data-search') || '';
        var ok = true;
        if (state.section !== 'all' && sec !== state.section) ok = false;
        if (ok && state.category !== 'all' && cat !== state.category) ok = false;
        if (ok && state.source !== 'all' && src !== state.source) ok = false;
        if (ok && state.query && hay.indexOf(state.query) === -1) ok = false;
        card.hidden = !ok;
        if (ok) visibleTotal++;
      });

      sections.forEach(function (secEl) {
        var secCards = secEl.querySelectorAll('article.card');
        var secVisible = 0;
        secCards.forEach(function (c) {
          if (!c.hidden) secVisible++;
        });
        secEl.hidden = secVisible === 0;
        var countEl = secEl.querySelector('.section-count');
        if (countEl) countEl.textContent = String(secVisible);
      });

      if (secWrap) {
        secWrap.querySelectorAll('[data-section]').forEach(function (btn) {
          var active = btn.getAttribute('data-section') === state.section;
          btn.classList.toggle('is-active', active);
          btn.setAttribute('aria-pressed', active ? 'true' : 'false');
        });
      }

      if (catWrap) {
        catWrap.querySelectorAll('[data-category]').forEach(function (btn) {
          var catVal = btn.getAttribute('data-category');
          var ownerSec = btn.getAttribute('data-owner-section') || 'all';
          var allowed = catVal === 'all' || state.section === 'all' || ownerSec === state.section;
          btn.hidden = !allowed;
          var active = catVal === state.category;
          btn.classList.toggle('is-active', active);
          btn.setAttribute('aria-pressed', active ? 'true' : 'false');
        });
      }

      if (summaryEl) {
        summaryEl.textContent = isZh
          ? ('当前展示 ' + visibleTotal + ' / ' + cards.length + ' 个条目')
          : ('Showing ' + visibleTotal + ' of ' + cards.length + ' entries');
      }

      if (emptyEl) emptyEl.hidden = visibleTotal > 0;
      if (clearBtn) {
        clearBtn.hidden = !(
          state.section !== 'all' ||
          state.category !== 'all' ||
          state.source !== 'all' ||
          state.query !== ''
        );
      }

      if (shouldSyncUrl) syncUrl();
    }

    if (secWrap) {
      secWrap.addEventListener('click', function (ev) {
        var btn = ev.target.closest('[data-section]');
        if (!btn) return;
        state.section = btn.getAttribute('data-section') || 'all';
        state.category = 'all';
        applyFilters(false);
      });
    }

    if (catWrap) {
      catWrap.addEventListener('click', function (ev) {
        var btn = ev.target.closest('[data-category]');
        if (!btn) return;
        state.category = btn.getAttribute('data-category') || 'all';
        applyFilters(false);
      });
    }

    searchInput.addEventListener('input', function () {
      state.query = searchInput.value.trim().toLowerCase();
      applyFilters(true);
    });

    sourceSelect.addEventListener('change', function () {
      state.source = sourceSelect.value || 'all';
      applyFilters(true);
    });

    if (searchForm) {
      searchForm.addEventListener('submit', function (ev) {
        ev.preventDefault();
        state.query = searchInput.value.trim().toLowerCase();
        state.source = sourceSelect.value || 'all';
        applyFilters(true);
      });
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', function () {
        state.section = 'all';
        state.category = 'all';
        state.source = 'all';
        state.query = '';
        searchInput.value = '';
        sourceSelect.value = 'all';
        applyFilters(true);
      });
    }

    document.addEventListener('keydown', function (ev) {
      var activeTag = document.activeElement ? document.activeElement.tagName : '';
      if (
        ev.key === '/' &&
        document.activeElement !== searchInput &&
        activeTag !== 'INPUT' &&
        activeTag !== 'TEXTAREA' &&
        activeTag !== 'SELECT' &&
        !ev.metaKey &&
        !ev.ctrlKey
      ) {
        ev.preventDefault();
        searchInput.focus();
      } else if (ev.key === 'Escape' && document.activeElement === searchInput) {
        searchInput.value = '';
        state.query = '';
        searchInput.blur();
        applyFilters(true);
      }
    });

    applyFilters(false);
  }
})();

(function () {
  var mc = (typeof document !== 'undefined' && document.modelContext)
    ? document.modelContext
    : (typeof navigator !== 'undefined' ? navigator.modelContext : null);
  if (!mc || typeof mc.registerTool !== 'function') return;

  if (typeof window !== 'undefined' && window.__nshAwesomeWebMcp && typeof window.__nshAwesomeWebMcp.dispose === 'function') {
    try { window.__nshAwesomeWebMcp.dispose(); } catch (e) {}
  }

  var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
  var signal = controller ? controller.signal : undefined;

  if (typeof window !== 'undefined' && controller) {
    window.__nshAwesomeWebMcp = {
      controller: controller,
      dispose: function () { controller.abort(); }
    };
    window.addEventListener('pagehide', function () {
      controller.abort();
    }, { once: true });
  }

  function loadCatalog() {
    if (typeof window !== 'undefined' && window.__NSH_AWESOME_CATALOG__ && Array.isArray(window.__NSH_AWESOME_CATALOG__.entries)) {
      return Promise.resolve(window.__NSH_AWESOME_CATALOG__);
    }
    var embedded = typeof document !== 'undefined' ? document.getElementById('nsh-index-data') : null;
    if (embedded && embedded.textContent) {
      try {
        var parsed = JSON.parse(embedded.textContent);
        if (parsed && Array.isArray(parsed.entries)) {
          if (typeof window !== 'undefined') window.__NSH_AWESOME_CATALOG__ = parsed;
          return Promise.resolve(parsed);
        }
      } catch (e) {}
    }
    if (typeof fetch === 'function') {
      return fetch('/index.json', { cache: 'default' })
        .then(function (res) { return res && res.ok ? res.json() : null; })
        .then(function (data) {
          if (data && Array.isArray(data.entries)) {
            if (typeof window !== 'undefined') window.__NSH_AWESOME_CATALOG__ = data;
            return data;
          }
          return null;
        })
        .catch(function () { return null; });
    }
    return Promise.resolve(null);
  }

  function formatEntry(entry, lang) {
    var zh = typeof lang === 'string' && lang.toLowerCase().indexOf('zh') === 0;
    return {
      id: entry.id,
      name: entry.name,
      section: entry.section,
      category: entry.category,
      kind: entry.kind,
      installable: Boolean(entry.installable),
      sourceType: entry.sourceType,
      installCommand: entry.installCommand || null,
      version: entry.version || null,
      nshVersion: entry.nshVersion || null,
      platforms: Array.isArray(entry.platforms) ? entry.platforms : [],
      license: entry.license || null,
      updatedAt: entry.updatedAt || null,
      sourceUrl: entry.sourceUrl || null,
      cratesUrl: entry.cratesUrl || null,
      homepage: entry.homepage || null,
      description: (entry.description && (entry.description[zh ? 'zh' : 'en'] || entry.description.en)) || '',
      notes: (entry.notes && (entry.notes[zh ? 'zh' : 'en'] || entry.notes.en)) || null
    };
  }

  var registerOpts = signal ? { signal: signal } : undefined;

  Promise.resolve(mc.registerTool({
    name: 'search_nshm_modules',
    title: 'Search Native Shell Modules',
    description: 'Search and filter the curated Awesome NSH catalog of installable nshm modules, framework crates, templates, and documentation. Read-only lookup over static site catalog data.',
    inputSchema: {
      type: 'object',
      properties: {
        query: {
          type: 'string',
          title: 'Search Query',
          description: 'Optional keyword to match module name, ID, description, platform, license, or install command.'
        },
        section: {
          type: 'string',
          title: 'Catalog Section',
          description: 'Filter by top-level catalog section.',
          enum: ['all', 'nshm', 'framework', 'templates', 'articles']
        },
        sourceType: {
          type: 'string',
          title: 'Distribution Source',
          description: 'Filter by package source type.',
          enum: ['all', 'crates.io', 'github', 'git', 'web']
        },
        platform: {
          type: 'string',
          title: 'Target Platform',
          description: 'Optional platform name filter such as macOS, iOS, Android, Linux, Windows, Web, GPUI, or HarmonyOS.'
        },
        installableOnly: {
          type: 'boolean',
          title: 'Installable Only',
          description: 'When true, return only modules verified as installable via nsh add.'
        },
        lang: {
          type: 'string',
          title: 'Language',
          description: 'Preferred language for descriptions and notes.',
          enum: ['en', 'zh']
        }
      }
    },
    annotations: {
      readOnlyHint: true,
      untrustedContentHint: false
    },
    execute: function (input) {
      var args = input && typeof input === 'object' ? input : {};
      var q = typeof args.query === 'string' ? args.query.trim().toLowerCase() : '';
      var section = typeof args.section === 'string' && args.section !== 'all' ? args.section : null;
      var sourceType = typeof args.sourceType === 'string' && args.sourceType !== 'all' ? args.sourceType : null;
      var platform = typeof args.platform === 'string' ? args.platform.trim().toLowerCase() : '';
      var installableOnly = Boolean(args.installableOnly);
      var lang = args.lang === 'zh' ? 'zh' : 'en';

      return loadCatalog().then(function (catalog) {
        if (!catalog || !Array.isArray(catalog.entries)) {
          return {
            content: [{
              type: 'text',
              text: JSON.stringify({ error: 'Catalog data is unavailable on this page.', results: [] })
            }]
          };
        }
        var matches = catalog.entries.filter(function (entry) {
          if (installableOnly && !entry.installable) return false;
          if (section && entry.section !== section) return false;
          if (sourceType && entry.sourceType !== sourceType) return false;
          if (platform) {
            var plats = (entry.platforms || []).map(function (p) { return String(p).toLowerCase(); });
            if (plats.indexOf(platform) === -1 && plats.indexOf('all') === -1) return false;
          }
          if (q) {
            var hay = [
              entry.id,
              entry.name,
              entry.kind,
              entry.sourceType,
              entry.installCommand || '',
              (entry.description && entry.description.en) || '',
              (entry.description && entry.description.zh) || '',
              (entry.notes && entry.notes.en) || '',
              (entry.notes && entry.notes.zh) || '',
              (entry.platforms || []).join(' '),
              entry.license || ''
            ].join(' ').toLowerCase();
            if (hay.indexOf(q) === -1) return false;
          }
          return true;
        });

        return {
          content: [{
            type: 'text',
            text: JSON.stringify({
              nshVerifiedVersion: catalog.nshVerifiedVersion || '0.7.1',
              totalMatches: matches.length,
              results: matches.slice(0, 25).map(function (item) { return formatEntry(item, lang); })
            }, null, 2)
          }]
        };
      });
    }
  }, registerOpts)).catch(function () {});

  Promise.resolve(mc.registerTool({
    name: 'get_nshm_install_command',
    title: 'Get Native Shell Module Install Command',
    description: 'Return the verified nsh add install command and package metadata for a specific Awesome NSH entry by ID or package name, distinguishing installable nshm modules from non-installable framework crates.',
    inputSchema: {
      type: 'object',
      properties: {
        idOrName: {
          type: 'string',
          title: 'Module ID or Name',
          description: 'Exact entry ID or package name (for example "nsh-omarchy", "nsh-widgets", or "nsh-core").'
        },
        lang: {
          type: 'string',
          title: 'Language',
          description: 'Preferred language for status notes and descriptions.',
          enum: ['en', 'zh']
        }
      },
      required: ['idOrName']
    },
    annotations: {
      readOnlyHint: true,
      untrustedContentHint: false
    },
    execute: function (input) {
      var args = input && typeof input === 'object' ? input : {};
      var target = typeof args.idOrName === 'string' ? args.idOrName.trim().toLowerCase() : '';
      var lang = args.lang === 'zh' ? 'zh' : 'en';

      return loadCatalog().then(function (catalog) {
        if (!catalog || !Array.isArray(catalog.entries)) {
          return {
            content: [{
              type: 'text',
              text: JSON.stringify({ found: false, error: 'Catalog data is unavailable on this page.' })
            }]
          };
        }
        var found = catalog.entries.find(function (entry) {
          return entry.id.toLowerCase() === target ||
            entry.name.toLowerCase() === target ||
            entry.id.toLowerCase() === 'crate-' + target;
        });
        if (!found) {
          return {
            content: [{
              type: 'text',
              text: JSON.stringify({
                found: false,
                query: args.idOrName || '',
                message: 'No matching entry found in Awesome NSH catalog.'
              }, null, 2)
            }]
          };
        }
        var payload = formatEntry(found, lang);
        payload.found = true;
        payload.nshVerifiedVersion = catalog.nshVerifiedVersion || '0.7.1';
        if (!found.installable) {
          payload.reason = found.section === 'framework'
            ? 'Official framework crate — NOT an installable nshm and cannot be installed with nsh add.'
            : 'Template or documentation entry — not an installable nshm package.';
        }
        return {
          content: [{
            type: 'text',
            text: JSON.stringify(payload, null, 2)
          }]
        };
      });
    }
  }, registerOpts)).catch(function () {});
})();
